function wireCharts(){for(const svg of document.querySelectorAll('[data-chart]')){const series=chartSets[n(svg.dataset.chart)],all=series.flatMap(s=>s.rows),min=Math.min(...all.map(r=>r.x)),max=Math.max(...all.map(r=>r.x));let current=min;
 function show(x){current=x;const parts=series.map(s=>{const r=s.rows.reduce((a,b)=>Math.abs(b.x-x)<Math.abs(a.x-x)?b:a);return `${s.name}: ${dollars(r.y)}${r.low!==undefined?` (${dollars(r.low)}–${dollars(r.high)})`:''}`;});const detail=svg.closest('.card')?.querySelector('.chart-detail');if(detail)detail.textContent=(min>3000?`${Math.floor(x/12)}-${String(x%12+1).padStart(2,'0')}`:String(x))+' · '+parts.join(' · ');}
 function pointer(e){const rect=svg.getBoundingClientRect(),px=(e.clientX-rect.left)/rect.width*1000,x=Math.round(min+clamp((px-75)/905,0,1)*(max-min));show(x);}svg.addEventListener('pointerdown',pointer);svg.addEventListener('pointermove',e=>{if(e.buttons||e.pointerType==='mouse')pointer(e);});svg.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();show(clamp(current+(e.key==='ArrowRight'?1:-1),min,max));}});}}
